#include <bits/stdc++.h>
using namespace std;const int N=48;const long long P=1e9+7;long long a[N][N],f[N],g[N];int id(int m,int u,int p){return(m*3+u)*4+p;}void d(int r,int m,int u,int p,int o,int c,int s){if(r==2){a[s][id(o,u,c)]++;return;}if(m>>r&1){d(r+1,m,u,p,o,c,s);return;}if(!r&&!(m&2))d(2,m,u,p,o,c,s);d(r+1,m,u,p,o|1<<r,c,s);if(u<2&&!c&&!(p>>r&1))d(r+1,m,u+1,p,o,c|1<<r,s);}int main(){ios::sync_with_stdio(0);cin.tie(0);for(int m=0;m<4;m++)for(int u=0;u<3;u++)for(int p=0;p<4;p++)d(0,m,u,p,0,0,id(m,u,p));int t;cin>>t;while(t--){int n;cin>>n;memset(f,0,sizeof f);f[0]=1;while(n--){memset(g,0,sizeof g);for(int i=0;i<N;i++)for(int j=0;j<N;j++)g[j]=(g[j]+f[i]*a[i][j])%P;memcpy(f,g,sizeof g);}long long r=0;for(int p=0;p<4;p++)r=(r+f[id(0,2,p)])%P;cout<<r<<'\n';}}
